enum class Mode : uint8_t { Off, Slow, Fast };

std::optional<Mode> parse_mode(uint8_t raw) {
    if (raw > static_cast<uint8_t>(Mode::Fast)) {
        return std::nullopt;   // reject bad input
    }
    return static_cast<Mode>(raw);
}

uint8_t duty_for(Mode m) {
    switch (m) {
        case Mode::Off:  return 0;
        case Mode::Slow: return 40;
        case Mode::Fast: return 90;
    }
    return 0;                  // safe default
}

