int log_write(const char *s) {
    if (strlen(s) > LOG_MAX) {
        return -1;               // before the lock
    }
    xSemaphoreTake(log_mtx, portMAX_DELAY);
    append(s);
    xSemaphoreGive(log_mtx);
    return 0;
}

